property.value:
let $atomics := ('java.util.concurrent.atomic.AtomicInteger', 'java.util.concurrent.atomic.AtomicLong',
                 'java.util.concurrent.atomic.AtomicBoolean', 'java.util.concurrent.atomic.AtomicReference'),
    $field := function($r) {
      $r[self::VariableAccess or self::FieldAccess[*[1][self::ThisExpression[not(*)]]]]
        [some $t in $atomics satisfies pmd-java:typeIs($t)]
    },
    $local := function($call, $n) {
      exists($call/ancestor::*[self::MethodDeclaration or self::ConstructorDeclaration or self::LambdaExpression]
               //VariableId[@Name = $n][not(parent::VariableDeclarator/parent::FieldDeclaration)])
    },
    $guarded := function($n) {
      exists($n/ancestor::SynchronizedStatement)
        or exists($n/ancestor::MethodDeclaration[1][pmd-java:modifiers() = 'synchronized'
             or .//MethodCall[@MethodName = ('lock', 'lockInterruptibly', 'tryLock')]])
    },
    $reads := function($g, $n) {
      exists($g[@MethodName = 'get'][ArgumentList/@Size = 0][*[1][@Name = $n][exists($field(.))]])
    }
return
//MethodCall[@MethodName = 'set'][ArgumentList/@Size = 1][exists($field(*[1]))]
  [not($guarded(.))]
  [let $n := string(*[1]/@Name)
   return ancestor::ClassBody[1]/FieldDeclaration/VariableDeclarator/VariableId[@Name = $n]
     and not($local(., $n))
     and ((some $g in ArgumentList//MethodCall satisfies $reads($g, $n))
          or (ArgumentList/BooleanLiteral
              and parent::ExpressionStatement/parent::Block[count(*) > 1]/parent::IfStatement
                    [*[1][self::MethodCall[$reads(., $n)]
                          or self::UnaryExpression[@Operator = '!']/MethodCall[$reads(., $n)]]]))]
